 private void load(int mode,int lesson){save();int n=lesson<0?prefs().getInt("level"+mode,0):lesson;n=Math.max(0,Math.min(ExplorerCatalog.count(mode)-1,n));state=new ExplorerState(mode,n);state.restore(prefs().getString("state"+mode+"-"+n,""));shapes=mode==4?new TangramState(n):null;if(shapes!=null){shapes.restore(prefs().getString("shapes"+n,""));state.won=shapes.won();}world=mode==5?readWorld(worldSlot):null;undoWorld=null;if(mode!=2&&state.won)wallet.creativeCompletion(state.rewardKey());reaction=1;render();}
