 private void control(String label,Runnable action){controls.addView(button(label,action),new LinearLayout.LayoutParams(-1,-2));}
 private void row(String[]labels,Runnable[]actions){LinearLayout row=new LinearLayout(this);for(int i=0;i<labels.length;i++)row.addView(button(labels[i],actions[i]),new LinearLayout.LayoutParams(0,-2,1));controls.addView(row);}
 private void refreshControls(){controls.removeAllViews();if(state.mode==2){control("Explore stop "+(selectedStop+1),this::openStop);control("Hear this stop",()->narrator.speak(stopDescription()));grid24(true);for(int i=0;i<6;i++){int count=0;for(int j=i*4;j<i*4+4;j++)if(completed[j])count++;controls.addView(text("Island "+(i+1)+" · "+count+" / 4 discoveries"+(count==4?" · milestone saved":""),16));}return;}if(state.mode==5){makerControls();return;}if(state.won){message.setText(ending());control(state.level+1==ExplorerCatalog.count(state.mode)?"Replay this studio":"Next discovery",()->{int m=state.mode,n=(state.level+1)%ExplorerCatalog.count(m);load(m,n);});control("Choose another activity",()->{save();menu();});return;}if(state.mode==0){ExplorerCatalog.Lesson q=ExplorerCatalog.LESSONS[state.level];String[]choices=q.choices();for(int i=0;i<3;i++){final int option=i;control(choices[i],()->choose(option));}control("Hear the question",()->narrator.speak(q.prompt));control("Show a clue",()->message.setText(q.hint));}
 else if(state.mode==1){if(state.level<26){if(!state.traced){controls.addView(text("Draw around the large letter. More than a tap is needed to explore its outline.",16));control("Hear this letter and word",()->narrator.speak(ExplorerCatalog.SOUNDS[state.level]));control("Match words instead of tracing",()->{state.traced=true;board.tracingDone=true;save();refreshControls();draw();});}else{String[]words=state.letterChoices();for(int i=0;i<3;i++){final int option=i;control(words[i],()->choose(option));}control("Hear the word to find",()->narrator.speak(ExplorerCatalog.SOUNDS[state.level]));}}else{String target=state.targetWord();controls.addView(text("Your word: "+(state.word.isEmpty()?"_ _ _":state.word),24));String letters=target+"Z";String[]labels=new String[4];Runnable[]actions=new Runnable[4];for(int i=0;i<4;i++){final char c=letters.charAt((i+state.level)%4);labels[i]=""+c;actions[i]=()->{state.addLetter(c);save();refreshControls();sound.note(state.word.length()%3);};}row(labels,actions);row(new String[]{"Undo letter","Check my word"},new Runnable[]{()->{state.undo();save();refreshControls();},()->{if(state.checkWord())win("You built "+state.targetWord()+"!");else message.setText("Look at the word above. Change a letter and try again.");}});control("Hear the word",()->narrator.speak(target.toLowerCase(java.util.Locale.ROOT)));}}
 else if(state.mode==3){ExplorerCatalog.Tale tale=ExplorerCatalog.TALES[state.level];control(state.phase==0?tale.a:tale.c,()->choose(0));control(state.phase==0?tale.b:tale.d,()->choose(1));control("Hear this story moment",()->narrator.speak(storyText()));}
 else if(state.mode==4){control("Rotate selected piece ↻",()->{shapes.rotate();save();draw();message.setText(TangramState.NAMES[shapes.selected]+" · "+shapes.rotation[shapes.selected]*45+"°");});control("Placement clue",()->message.setText("Try "+TangramState.NAMES[shapes.selected]+" at outline "+(shapes.selected+1)+", turned "+shapes.targetRotation(shapes.selected)*45+"°. Rotate, then drag or use its outline button."));HorizontalScrollView pieces=new HorizontalScrollView(this);LinearLayout strip=new LinearLayout(this);for(int i=0;i<7;i++){final int piece=i;strip.addView(button(TangramState.NAMES[i],()->{shapes.selected=piece;draw();message.setText(TangramState.NAMES[piece]+" selected");}),new LinearLayout.LayoutParams(dp(140),dp(80)));}pieces.addView(strip);controls.addView(pieces);controls.addView(text("Accessible placement: choose a piece, rotate it, then choose its outline.",16));HorizontalScrollView targets=new HorizontalScrollView(this);LinearLayout targetStrip=new LinearLayout(this);for(int i=0;i<7;i++){final int target=i;targetStrip.addView(button("Outline "+(i+1),()->{if(shapes.place(shapes.selected,target)){if(shapes.won())win("All seven pieces fit!");else{sound.note(shapes.count()%3);save();draw();message.setText(shapes.count()+" / 7 fitted");}}else message.setText("Check this piece's shape, size and rotation. An empty matching outline is needed.");}),new LinearLayout.LayoutParams(dp(96),dp(64)));}targets.addView(targetStrip);controls.addView(targets);}}
 private String ending(){if(state.mode==3){ExplorerCatalog.Tale t=ExplorerCatalog.TALES[state.level];return state.second==0?t.endingC:t.endingD;}return "Discovery saved · first clear earns 1 star and 5 coins. Replay whenever you like.";}
 private String storyText(){ExplorerCatalog.Tale t=ExplorerCatalog.TALES[state.level];if(state.phase==0)return t.setup;if(state.phase==1)return (state.first==0?t.resultA:t.resultB)+" "+t.question;return state.second==0?t.endingC:t.endingD;}
 private void choose(int option){int before=state.phase;if(state.answer(option))win(state.mode==3?storyText():"Well explored! Your discovery is saved.");else if(state.mode==3&&state.phase!=before){save();refreshControls();animateFriends();draw();}else{message.setText(state.mode==0?ExplorerCatalog.LESSONS[state.level].hint:"Listen to the word and look at its letters. Try another choice.");sound.note(0);}save();draw();}
 private void animateFriends(){if(transition!=null)transition.cancel();if(reduced()){reaction=1;return;}reaction=0;transition=android.animation.ValueAnimator.ofFloat(0,1);transition.setDuration(550);transition.setInterpolator(new android.view.animation.AccelerateDecelerateInterpolator());transition.addUpdateListener(a->{reaction=(Float)a.getAnimatedValue();draw();});transition.start();}
 private void win(String explanation){state.won=true;wallet.creativeCompletion(state.rewardKey());save();sound.win();refreshControls();message.setText(explanation);draw();}
 private void refreshMap(){for(int i=0;i<24;i++)completed[i]=progress.completed(ExplorerCatalog.stopKey(i));for(int island=0;island<6;island++){boolean all=true;for(int i=island*4;i<island*4+4;i++)all&=completed[i];if(all)wallet.creativeCompletion("island-"+island);}if(board!=null)board.stops=completed.clone();}
 private String stopDescription(){int mode=ExplorerCatalog.stopMode(selectedStop);String name=mode<0?LearningQuest.NAMES[-mode-1]:ExplorerCatalog.NAMES[mode];return "Stop "+(selectedStop+1)+" · "+name+" · stage "+(ExplorerCatalog.stopStage(selectedStop)+1)+(completed[selectedStop]?" · completed":"");}
 private void selectStop(int stop){if(stop<0||stop>=24)return;selectedStop=stop;board.selected=stop;save();refreshControls();draw();}
 private void openStop(){save();int mode=ExplorerCatalog.stopMode(selectedStop),lesson=ExplorerCatalog.stopStage(selectedStop);if(mode<0)startActivity(new Intent(this,QuestActivity.class).putExtra("mode",-mode-1).putExtra("quest_stage",lesson));else startActivity(new Intent(this,StudioActivity.class).putExtra("mode",mode).putExtra("lesson",lesson));}
 private void grid24(boolean map){for(int row=0;row<8;row++){String[]labels=new String[3];Runnable[]actions=new Runnable[3];for(int col=0;col<3;col++){final int slot=row*3+col;labels[col]=(map?"Stop ":"Space ")+(slot+1)+(map&&completed[slot]?" ✓":"");actions[col]=()->{if(map)selectStop(slot);else{world.select(slot);board.selected=slot;draw();message.setText("Space "+(slot+1)+" selected. Choose an item or paint on the board.");}};}row(labels,actions);}}
 private void makerControls(){control("Hear this building challenge",()->narrator.speak(MakerState.CHALLENGES[state.level]));HorizontalScrollView tray=new HorizontalScrollView(this);LinearLayout strip=new LinearLayout(this);for(int i=0;i<6;i++){final int item=i;strip.addView(button(MakerState.ITEMS[i],()->{undoWorld=world.save();world.place(item);save();draw();message.setText(MakerState.ITEMS[item]+" placed. Tap another space to paint more.");}),new LinearLayout.LayoutParams(dp(100),dp(64)));}tray.addView(strip);controls.addView(tray);row(new String[]{"Rotate piece","Erase space","Undo"},new Runnable[]{()->{undoWorld=world.save();world.rotate();save();draw();},()->{undoWorld=world.save();world.clear();save();draw();},()->{if(undoWorld!=null){String current=world.save();world.restore(undoWorld);undoWorld=current;save();draw();}}});control("Check my building challenge",()->{if(world.meets(state.level)){if(!state.won){state.won=true;wallet.creativeCompletion(state.rewardKey());sound.win();}save();message.setText("Your world meets this challenge! Your first-clear reward is saved.");draw();}else message.setText("Keep making: "+MakerState.CHALLENGES[state.level]+". You can also play freely.");});control(state.level==11?"Replay building challenges":"Next building challenge",()->load(5,(state.level+1)%12));controls.addView(text("Your worlds stay on this device. Choose a world, then build freely; challenge rewards are optional.",16));HorizontalScrollView worlds=new HorizontalScrollView(this);LinearLayout slots=new LinearLayout(this);for(int i=0;i<6;i++){final int slot=i;slots.addView(button("World "+(i+1),()->{save();worldSlot=slot;world=readWorld(slot);undoWorld=null;board.selected=world.selected;save();draw();message.setText("World "+(slot+1)+" opened.");}),new LinearLayout.LayoutParams(dp(96),dp(64)));}worlds.addView(slots);controls.addView(worlds);grid24(false);}
