 private void draw(){if(state==null)return;status.setText((state.mode==2?"24 stops":(state.mode==5?"World "+(worldSlot+1)+" · Challenge ":"Discovery ")+(state.level+1)+" / "+ExplorerCatalog.count(state.mode))+" · "+wallet.stars()+" stars");if(state.mode==0)title.setText(ExplorerCatalog.LESSONS[state.level].prompt);else if(state.mode==1)title.setText(state.level<26?((char)('A'+state.level))+" · "+(state.traced?"Find the matching word":"Trace the outline"):"Build "+state.targetWord());else if(state.mode==2)title.setText(stopDescription());else if(state.mode==3)title.setText(ExplorerCatalog.TALES[state.level].title+"\n"+storyText());else if(state.mode==4)title.setText("Fit seven pieces · "+shapes.count()+" / 7");else title.setText(MakerState.CHALLENGES[state.level]);if(board!=null){board.selected=state.mode==2?selectedStop:state.mode==5?world.selected:0;board.invalidate();}if(stage!=null)stage.submit(ExplorerScenes.build(state,shapes,world,completed,theme,wallet.skinColor(),reaction));}
