 @Override protected void onPause(){paused=true;save();if(transition!=null)transition.cancel();if(stage!=null)stage.onPause();narrator.stop();sound.stop();super.onPause();}
 @Override protected void onResume(){super.onResume();paused=false;long g=getSharedPreferences("family",0).getLong("quest_reset_generation",0);if(g!=generation){generation=g;state=null;world=null;shapes=null;menu();}else if(resumed&&state!=null){if(state.mode==2)refreshMap();render();}else if(stage!=null)stage.onResume();resumed=true;}
